<template>
  <el-card class="jxkh-card">
    <template #header>
      <div class="card-header">
        <span>绩效考核</span>
        <el-tag type="info" size="small">jxkh</el-tag>
      </div>
    </template>

    <el-tabs v-model="activeTab" type="border-card">
      <!-- 数据匹配 -->
      <el-tab-pane label="数据匹配" name="sjpp">
        <el-form label-width="140px">
          <el-form-item label="本月原始表">
            <el-upload
              ref="uploadSource"
              drag
              :auto-upload="false"
              :limit="1"
              :on-change="handleSourceChange"
              accept=".xlsx,.xls"
            >
              <el-icon class="el-icon--upload"><UploadFilled /></el-icon>
              <div class="el-upload__text">将文件拖到此处，或 <em>点击选择</em></div>
            </el-upload>
          </el-form-item>
          <el-form-item label="上月（已核对）">
            <el-upload
              ref="uploadPrev"
              drag
              :auto-upload="false"
              :limit="1"
              :on-change="handlePrevChange"
              accept=".xlsx,.xls"
            >
              <el-icon class="el-icon--upload"><UploadFilled /></el-icon>
              <div class="el-upload__text">将文件拖到此处，或 <em>点击选择</em></div>
            </el-upload>
          </el-form-item>
          <el-form-item>
            <el-button type="success" :loading="loading" @click="submitSjpp">开始生成</el-button>
          </el-form-item>
        </el-form>
        <el-alert
          title="说明：程序会自动识别以'代工费-' / '百事通报备名单-' / '员工信息汇总-'开头的工作表。"
          type="info"
          :closable="false"
          style="margin-top: 12px"
        />
      </el-tab-pane>

      <!-- 稳岗率分析 -->
      <el-tab-pane label="稳岗率分析" name="wgl">
        <el-form label-width="140px">
          <el-form-item label="Excel文件">
            <el-upload
              ref="uploadWgl"
              drag
              :auto-upload="false"
              :limit="1"
              :on-change="handleWglFileChange"
              accept=".xlsx,.xls"
            >
              <el-icon class="el-icon--upload"><UploadFilled /></el-icon>
              <div class="el-upload__text">将文件拖到此处，或 <em>点击选择</em></div>
            </el-upload>
          </el-form-item>
          <el-form-item label="工作表名称">
            <el-select v-model="formWgl.sheetName" placeholder="请选择工作表" style="width: 220px">
              <el-option v-for="s in wglSheets" :key="s" :label="s" :value="s" />
            </el-select>
          </el-form-item>
          <el-form-item label="起始月份">
            <el-config-provider :locale="customLocale">
              <el-date-picker
                v-model="formWgl.startMonth"
                type="month"
                format="YYYY/MM"
                value-format="YYYY/MM"
                placeholder="选择起始月份"
                style="width: 220px"
              />
            </el-config-provider>
          </el-form-item>
          <el-form-item label="结束月份">
            <el-config-provider :locale="customLocale">
              <el-date-picker
                v-model="formWgl.endMonth"
                type="month"
                format="YYYY/MM"
                value-format="YYYY/MM"
                placeholder="选择结束月份"
                style="width: 220px"
              />
            </el-config-provider>
          </el-form-item>
          <el-form-item label="保留原始工作表">
            <el-switch v-model="formWgl.copyOriginal" active-text="是" inactive-text="否" />
          </el-form-item>
          <el-form-item>
            <el-button type="success" :loading="loading" @click="submitWgl">开始分析</el-button>
          </el-form-item>
        </el-form>
        <!-- 操作日志 -->
        <div v-if="wglLogs.length" class="log-panel">
          <div class="log-title">处理日志</div>
          <div v-for="(log, idx) in wglLogs" :key="idx" class="log-line">{{ log }}</div>
        </div>

        <el-alert
          title="说明：生成项目驻场、项目经理、稳岗率、奖励汇总、基准数 5张工作表。"
          type="info"
          :closable="false"
          style="margin-top: 12px"
        />
      </el-tab-pane>

      <!-- 合并表格 -->
      <el-tab-pane label="合并表格" name="hbbg">
        <!-- 模式切换 -->
        <el-radio-group v-model="hbbgMode" @change="onHbbgModeChange" style="margin-bottom:12px">
          <el-radio-button value="process">处理模式（填月份列）</el-radio-button>
          <el-radio-button value="generic">通用合并（原样堆叠）</el-radio-button>
        </el-radio-group>

        <!-- 文件选择 -->
        <el-upload
          ref="uploadHbbg"
          drag
          :auto-upload="false"
          multiple
          :on-change="handleHbbgFilesChange"
          accept=".xlsx,.xls"
        >
          <el-icon class="el-icon--upload"><UploadFilled /></el-icon>
          <div class="el-upload__text">将文件拖到此处，或 <em>点击选择</em></div>
        </el-upload>


        <!-- 处理模式参数 -->
        <el-form v-if="hbbgMode === 'process'" label-width="140px" style="margin-top:12px">
          <el-form-item label="目标列字母">
            <el-input v-model="formHbbg.targetCol" placeholder="如 AU" style="width: 120px" />
          </el-form-item>
        </el-form>

        <!-- 通用合并模式参数 -->
        <el-form v-if="hbbgMode === 'generic'" label-width="140px" style="margin-top:12px">
          <el-form-item label="文件间空行数">
            <el-input-number v-model="formHbbg.gapRows" :min="0" :max="100" style="width:120px" />
            <span style="margin-left:8px;color:#888;font-size:12px">行（0=不插空行）</span>
          </el-form-item>
          <el-form-item label="保留表头文件">
            <el-select v-model="formHbbg.keepHeaderFile" placeholder="（不指定）" clearable style="width:320px" :disabled="hbbgFiles.length === 0">
              <el-option v-for="(f, idx) in hbbgFiles" :key="idx" :label="f.name" :value="f.name" />
            </el-select>
            <span style="margin-left:8px;color:#888;font-size:12px">不选则全部保留表头</span>
          </el-form-item>
          <el-form-item label="跳过表头行数">
            <el-input-number v-model="formHbbg.skipRows" :min="0" :max="100" style="width:120px" />
            <span style="margin-left:8px;color:#888;font-size:12px">行（其余文件跳过前N行）</span>
          </el-form-item>
        </el-form>

        <el-button type="success" :loading="loading" @click="submitHbbg" style="margin-top:12px">
          {{ hbbgMode === 'process' ? '开始合并' : '开始合并' }}
        </el-button>
        <el-progress v-if="hbbgProgress > 0 && hbbgProgress < 100" :percentage="Math.round(hbbgProgress)" style="margin-top:8px" />
      </el-tab-pane>
    </el-tabs>

    <!-- 下载区域 -->
    <el-card v-if="downloadFileName" style="margin-top: 16px">
      <span>处理完成：{{ downloadFileName }}</span>
      <el-button type="primary" style="margin-left: 12px" @click="downloadFile(downloadFileName)">
        下载文件
      </el-button>
    </el-card>

    <el-alert
      v-if="message && !downloadFileName"
      :title="message"
      :type="messageType"
      show-icon
      closable
      style="margin-top: 16px"
      @close="message = ''"
    />
  </el-card>
</template>

<script>
import axios from 'axios'
import zhCn from 'element-plus/dist/locale/zh-cn.mjs'

const customLocale = {
  ...zhCn,
  el: {
    ...zhCn.el,
    datepicker: {
      ...zhCn.el.datepicker,
      month1: '1月',
      month2: '2月',
      month3: '3月',
      month4: '4月',
      month5: '5月',
      month6: '6月',
      month7: '7月',
      month8: '8月',
      month9: '9月',
      month10: '10月',
      month11: '11月',
      month12: '12月',
      months: {
        ...zhCn.el.datepicker.months,
        jan: '1月', feb: '2月', mar: '3月', apr: '4月',
        may: '5月', jun: '6月', jul: '7月', aug: '8月',
        sep: '9月', oct: '10月', nov: '11月', dec: '12月'
      }
    }
  }
}

export default {
  name: 'JxkhCard',
  data() {
    return {
      activeTab: 'sjpp',
      loading: false,
      message: '',
      messageType: 'info',
      downloadFileName: '',
      sourceFile: null,
      prevFile: null,
      wglFile: null,
      wglSheets: [],
      wglLogs: [],
      hbbgFiles: [],
      hbbgMode: 'process',
      hbbgProgress: 0,
      customLocale: customLocale,
      formWgl: {
        sheetName: '',
        startMonth: '',
        endMonth: '',
        copyOriginal: true
      },
      formHbbg: {
        targetCol: '',
        gapRows: 0,
        keepHeaderFile: '',
        skipRows: 1
      }
    }
  },
  methods: {
    handleSourceChange(file) {
      this.sourceFile = file.raw
    },
    handlePrevChange(file) {
      this.prevFile = file.raw
    },
    handleWglFileChange(file) {
      this.wglFile = file.raw
      this.wglSheets = []
      this.formWgl.sheetName = ''
      if (file.raw) {
        this.loadWglSheets(file.raw)
      }
    },
    loadWglSheets(file) {
      const formData = new FormData()
      formData.append('file', file)
      axios.post('/api/finance/toolbox/sheets', formData).then(res => {
        if (res.data.success) {
          this.wglSheets = res.data.sheets || []
          if (this.wglSheets.length > 0) {
            this.formWgl.sheetName = this.wglSheets[0]
          }
        } else {
          this.showMessage(res.data.message || '读取工作表失败', 'warning')
        }
      }).catch(err => {
        this.showMessage(err.response?.data?.message || err.message, 'error')
      })
    },
    handleHbbgFilesChange(file, fileList) {
      this.hbbgFiles = fileList.map(f => f.raw)
    },
    showMessage(text, type = 'info') {
      this.message = text
      this.messageType = type
    },
    submitSjpp() {
      if (!this.sourceFile) {
        this.showMessage('请选择本月原始表', 'warning')
        return
      }
      const formData = new FormData()
      formData.append('sourceFile', this.sourceFile)
      if (this.prevFile) formData.append('prevFile', this.prevFile)
      this.post('/api/finance/jxkh/sjpp', formData)
    },
    submitWgl() {
      if (!this.wglFile) {
        this.showMessage('请选择Excel文件', 'warning')
        return
      }
      if (!this.formWgl.startMonth || !this.formWgl.endMonth) {
        this.showMessage('请填写起始和结束月份', 'warning')
        return
      }
      this.wglLogs = []
      const formData = new FormData()
      formData.append('file', this.wglFile)
      if (this.formWgl.sheetName) formData.append('sheetName', this.formWgl.sheetName)
      formData.append('startMonth', this.formWgl.startMonth)
      formData.append('endMonth', this.formWgl.endMonth)
      formData.append('copyOriginal', this.formWgl.copyOriginal)
      this.post('/api/finance/jxkh/wgl', formData, (res) => {
        if (res.data.logs && res.data.logs.length) {
          this.wglLogs = res.data.logs
        }
      })
    },
    removeHbbgFile(idx) {
      this.hbbgFiles.splice(idx, 1)
    },
    onHbbgModeChange() {
      this.downloadFileName = ''
      this.message = ''
      this.hbbgProgress = 0
    },
    submitHbbg() {
      if (this.hbbgFiles.length === 0) {
        this.showMessage('请选择至少一个Excel文件', 'warning')
        return
      }
      const formData = new FormData()
      this.hbbgFiles.forEach(f => formData.append('files', f))

      if (this.hbbgMode === 'process') {
        if (!this.formHbbg.targetCol) {
          this.showMessage('请填写目标列字母', 'warning')
          return
        }
        formData.append('targetCol', this.formHbbg.targetCol)
        this.post('/api/finance/jxkh/hbbg', formData)
      } else {
        formData.append('gapRows', this.formHbbg.gapRows)
        formData.append('keepHeaderFile', this.formHbbg.keepHeaderFile || '')
        formData.append('skipRows', this.formHbbg.skipRows)
        this.hbbgProgress = 10
        this.post('/api/finance/jxkh/hbbg-generic', formData, () => { this.hbbgProgress = 100 })
      }
    },
    post(endpoint, formData, onSuccess) {
      this.loading = true
      this.message = ''
      this.downloadFileName = ''
      // FormData 上传不能手动设置 Content-Type，浏览器会自动设置并带上 boundary
      axios.post(endpoint, formData).then(res => {
        if (res.data.success) {
          this.showMessage(res.data.message, 'success')
          this.downloadFileName = res.data.fileName
          if (typeof onSuccess === 'function') onSuccess(res)
        } else {
          this.showMessage(res.data.message || '处理失败', 'error')
        }
      }).catch(err => {
        this.showMessage(err.response?.data?.message || err.message, 'error')
      }).finally(() => {
        this.loading = false
      })
    },
    downloadFile(fileName) {
      const url = '/api/finance/download/' + encodeURIComponent(fileName)
      const link = document.createElement('a')
      link.href = url
      link.download = fileName
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
    }
  }
}
</script>

<style scoped src="../styles/components/JxkhCard.css"></style>
