        </el-form>
        <div class="tb-section-title">操作</div>
        <el-button type="success" :loading="loading" @click="submitDataCompare">开始比较</el-button>
        <el-button style="margin-left: 8px" @click="refreshTab('data-compare')">
          <el-icon><Refresh /></el-icon> 刷新
