                <template #default="{ row }">{{ row.amountRight.toFixed(2) }}</template>
              </el-table-column>
              <el-table-column prop="remark" label="备注" min-width="120" />
              <el-table-column prop="unit" label="运营中心" min-width="90" />
            </el-table>
            <el-descriptions :column="3" border style="margin-top: 12px">
              <el-descriptions-item label="总记录数">{{ comparePreview.totalCount }}</el-descriptions-item>
              <el-descriptions-item label="相符(TRUE)"><span style="color:green">{{ comparePreview.trueCount }}</span></el-descriptions-item>
              <el-descriptions-item label="不符(FALSE)"><span style="color:red">{{ comparePreview.falseCount }}</span></el-descriptions-item>
              <el-descriptions-item label="申请表总金额">{{ comparePreview.sumLeft.toFixed(2) }}</el-descriptions-item>
              <el-descriptions-item label="差额总计">{{ comparePreview.sumDiff.toFixed(2) }}</el-descriptions-item>
              <el-descriptions-item label="明细表总金额">{{ comparePreview.sumRight.toFixed(2) }}</el-descriptions-item>
            </el-descriptions>
            <el-alert
              v-if="comparePreview.falseCount > 0"
              :title="'有 ' + comparePreview.falseCount + ' 条记录不符，请检查'"
              type="warning"
              :closable="false"
              style="margin-top: 12px"
            />
            <el-button type="primary" style="margin-top: 12px" @click="downloadFile(compareFileName)">下载完整结果</el-button>
          </el-card>
        </div>
      </el-tab-pane>

      <!-- 报销拆分 -->
      <el-tab-pane label="报销拆分" name="expense-split">
        <div class="tb-section-title">步骤1：上传文件</div>
        <el-upload
          ref="uploadExpense"
          class="tb-upload"
          drag
          :auto-upload="false"
          :limit="1"
          :on-change="handleExpenseFileChange"
          accept=".xlsx"
        >
          <el-icon class="tb-upload-icon"><UploadFilled /></el-icon>
          <div>将文件拖到此处，或 <em>点击选择</em></div>
          <div v-if="formExpense.file" class="tb-file-name">{{ formExpense.file.name }}</div>
        </el-upload>
        <div class="tb-section-title" style="margin-top: 16px">步骤2：处理预览</div>
        <el-button type="primary" :loading="expensePreviewing" :disabled="!formExpense.file" @click="submitExpensePreview">处理并预览列名</el-button>
        <el-card v-if="expensePreviewCols.length > 0" style="margin-top: 12px">
          <template #header>处理后列名（共 {{ expensePreviewCols.length }} 列）</template>
          <div style="max-height:200px;overflow:auto">
            <el-tag v-for="(col, idx) in expensePreviewCols" :key="idx" style="margin:2px 4px">{{ idx + 1 }}. {{ col }}</el-tag>
          </div>
        </el-card>
        <div class="tb-section-title" style="margin-top: 16px">步骤3：选择拆分列并执行</div>
        <el-form label-position="top" style="margin-top: 8px">
          <el-form-item label="拆分列">
            <el-select v-model="formExpense.splitColumn" placeholder="请选择拆分列" style="width:100%">
              <el-option v-for="(col, idx) in expensePreviewCols" :key="idx" :label="col" :value="col" />
            </el-select>
          </el-form-item>
        </el-form>
        <div class="tb-section-title">操作</div>
        <el-button type="success" :loading="loading" :disabled="!formExpense.splitColumn" @click="submitExpenseSplit">执行拆分</el-button>
        <el-button style="margin-left: 8px" @click="refreshTab('expense-split')">
          <el-icon><Refresh /></el-icon> 刷新
        </el-button>
        <el-card v-if="expenseDownloadName" style="margin-top: 16px">
          <span>处理完成：{{ expenseDownloadName }}</span>
          <el-button type="primary" style="margin-left: 12px" @click="downloadFile(expenseDownloadName)">下载文件</el-button>
        </el-card>
      </el-tab-pane>

      <!-- 代工费拆分 -->
      <el-tab-pane label="代工费拆分_批量处理" name="labor-split">
        <div class="tb-section-title">上传文件</div>
        <el-row :gutter="16">
          <el-col :span="12">
            <div class="tb-upload-label">
              代工费表格（支持多选）
              <el-tag v-if="formLabor.files1.length > 0" size="small" type="info" style="margin-left: 8px">{{ formLabor.files1.length }} 个文件</el-tag>
            </div>
            <el-upload
              ref="uploadLabor1"
              class="tb-upload"
              drag
              :auto-upload="false"
              :multiple="true"
              :on-change="(f) => handleLaborFileChange('file1', f)"
              accept=".xlsx"
            >
              <el-icon class="tb-upload-icon"><UploadFilled /></el-icon>
              <div>将文件拖到此处，或 <em>点击选择</em></div>
            </el-upload>
            <el-form label-position="top" style="margin-top: 8px">
              <el-form-item label="工作表名">
                <el-select v-model="formLabor.sheet1Name" placeholder="请选择工作表" style="width:100%" :disabled="laborSheets1.length === 0">
                  <el-option v-for="s in laborSheets1" :key="s" :label="s" :value="s" />
                </el-select>
              </el-form-item>
            </el-form>
          </el-col>
          <el-col :span="12">
            <div class="tb-upload-label">发放记录表格</div>
            <el-upload
              ref="uploadLabor2"
              class="tb-upload"
              drag
              :auto-upload="false"
              :limit="1"
              :on-change="(f) => handleLaborFileChange('file2', f)"
              accept=".xlsx"
            >
              <el-icon class="tb-upload-icon"><UploadFilled /></el-icon>
              <div>将文件拖到此处，或 <em>点击选择</em></div>
              <div v-if="formLabor.file2" class="tb-file-name">{{ formLabor.file2.name }}</div>
            </el-upload>
            <el-form label-position="top" style="margin-top: 8px">
              <el-form-item label="工作表A（拆分写入）">
                <el-select v-model="formLabor.sheet2Name" placeholder="请选择工作表" style="width:100%">
                  <el-option v-for="s in laborSheets2" :key="s" :label="s" :value="s" />
                </el-select>
              </el-form-item>
              <el-form-item label="工作表B（汇总参考）">
                <el-select v-model="formLabor.sheetBName" placeholder="请选择工作表" style="width:100%">
                  <el-option v-for="s in laborSheets2" :key="s" :label="s" :value="s" />
                </el-select>
              </el-form-item>
            </el-form>
          </el-col>
        </el-row>
        <div class="tb-section-title" style="margin-top: 16px">操作</div>
        <el-button type="success" :loading="loading" @click="submitLaborSplit">开始拆分</el-button>
        <el-button style="margin-left: 8px" @click="refreshTab('labor-split')">
          <el-icon><Refresh /></el-icon> 刷新
        </el-button>
        <el-card v-if="laborDownloadName" style="margin-top: 16px">
          <div style="margin-bottom: 8px">处理完成，请下载以下文件：</div>
          <div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:8px">
            <el-tag type="primary">发放记录表（含拆分结果）</el-tag>
            <el-button type="primary" size="small" @click="downloadFile(laborDownloadName)">下载文件</el-button>
          </div>
          <div v-for="(name, idx) in laborSummaryFileNames" :key="idx" style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:8px">
            <el-tag type="success">{{ name }}</el-tag>
            <el-button type="success" size="small" @click="downloadFile(name)">下载文件</el-button>
          </div>
        </el-card>
        <!-- 代工费拆分操作日志 -->
        <el-card v-if="laborLogs.length > 0" header="处理日志" style="margin-top: 16px">
          <div class="labor-log-box">
            <div v-for="(log, idx) in laborLogs" :key="idx" class="labor-log-line">{{ log }}</div>
          </div>
        </el-card>
      </el-tab-pane>
    </el-tabs>

    <!-- 全局消息提示 -->
    <el-alert
      v-if="message && !comparePreview && !feeDownloadName && !expenseDownloadName && !laborDownloadName"
      :title="message"
      :type="messageType"
      show-icon
      closable
      style="margin-top: 16px"
      @close="message = ''"
    />
  </el-card>
</template>

<script>
import axios from 'axios'

export default {
  name: 'ToolboxCard',
  // 注意：不再监听 activeTab，切换 Tab 保留所有操作记录和下载
  data() {
    return {
      activeTab: 'fee-split',
      loading: false,
      message: '',
      messageType: 'info',
      feeFile: null,
      formCompare: {
        file1: null,
        file2: null,
        sheet1Name: '',
        sheet2Name: '',
        startDate: '',
        endDate: ''
      },
      compareSheets1: [],
      compareSheets2: [],
      comparePreview: null,
      comparePreviewRows: [],
      compareFileName: '',
      // 每个Tab独立持有下载文件名（切换不清除）
      feeDownloadName: '',           // 手续费拆分
      expenseDownloadName: '',       // 报销拆分
      laborDownloadName: '',         // 代工费拆分 - 发放记录表
      laborSummaryFileNames: [],     // 代工费拆分 - 汇总文件列表
      formExpense: {
        file: null,
        splitColumn: ''
      },
      expensePreviewing: false,
      expensePreviewCols: [],
      formLabor: {
        files1: [],       // 代工费表格（多文件）对齐 Python file1_list
        file2: null,      // 发放记录表格
        sheet1Name: '',   // 工作表名（逗号分隔，与文件顺序对应）
        sheet2Name: '',   // 工作表A
        sheetBName: ''    // 工作表B
      },
      laborSheets1: [],
      laborSheets2: [],
      laborLogs: [],
      laborSplitting: false
    }
  },
  methods: {
    handleFeeFileChange(file) {
      this.feeFile = file.raw
    },
    handleFileChange(key, file, type) {
      const raw = file.raw
      if (type === 'compare') {
        this.formCompare[key] = raw
        const target = key === 'file1' ? 'compareSheets1' : 'compareSheets2'
        const sheetKey = key === 'file1' ? 'sheet1Name' : 'sheet2Name'
        this.loadSheets(raw, target, sheetKey)
      }
    },
    handleExpenseFileChange(file) {
      this.formExpense.file = file.raw
    },
    handleLaborFileChange(key, file) {
      if (key === 'file1') {
        // 多文件模式：追加到数组
        const raw = file.raw
        if (!this.formLabor.files1.find(f => f.name === raw.name && f.size === raw.size)) {
          this.formLabor.files1.push(raw)
        }
        // 加载第一个文件的工作表列表
        if (this.formLabor.files1.length === 1) {
          this.loadSheets(raw, 'laborSheets1', 'sheet1Name')
        }
      } else {
        this.formLabor.file2 = file.raw
        this.loadSheets(file.raw, 'laborSheets2', 'sheet2Name')
      }
    },
    removeLaborFile(idx) {
      this.formLabor.files1.splice(idx, 1)
      if (this.formLabor.files1.length === 0) {
        this.laborSheets1 = []
        this.formLabor.sheet1Name = ''
      }
    },
    loadSheets(file, listKey, selectKey) {
      const formData = new FormData()
      formData.append('file', file)
      // FormData 上传不能手动设置 Content-Type，浏览器会自动设置并带上 boundary
      axios.post('/api/finance/toolbox/sheets', formData).then(res => {
        if (res.data.success) {
          this[listKey] = res.data.sheets || []
          if (this[listKey].length > 0 && !this[selectKey]) {
            this[selectKey] = this[listKey][0]
          }
        } else {
          this.showMessage(res.data.message || '读取工作表失败', 'warning')
        }
      }).catch(err => {
        this.showMessage(err.response?.data?.message || err.message, 'error')
      })
    },
    showMessage(text, type = 'info') {
      this.message = text
      this.messageType = type
    },
    submitFeeSplit() {
      if (!this.feeFile) {
        this.showMessage('请先选择文件', 'warning')
        return
      }
      const formData = new FormData()
      formData.append('file', this.feeFile)
      this.loading = true
      this.message = ''
      axios.post('/api/finance/toolbox/fee-split', formData).then(res => {
        if (res.data.success) {
          this.showMessage(res.data.message, 'success')
          this.feeDownloadName = res.data.fileName
        } else {
          this.showMessage(res.data.message || '处理失败', 'error')
        }
      }).catch(err => {
        this.showMessage(err.response?.data?.message || err.message, 'error')
      }).finally(() => {
        this.loading = false
      })
    },
    submitDataCompare() {
      if (!this.formCompare.file1 || !this.formCompare.file2) {
        this.showMessage('请先选择两个文件', 'warning')
        return
      }
      if (!this.formCompare.sheet1Name || !this.formCompare.sheet2Name) {
        this.showMessage('请先选择工作表', 'warning')
        return
      }
      this.loading = true
      this.message = ''
      const formData = new FormData()
      formData.append('file1', this.formCompare.file1)
      formData.append('file2', this.formCompare.file2)
      formData.append('sheet1Name', this.formCompare.sheet1Name)
      formData.append('sheet2Name', this.formCompare.sheet2Name)
      formData.append('startDate', this.formCompare.startDate)
      formData.append('endDate', this.formCompare.endDate)
      axios.post('/api/finance/toolbox/data-compare', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      }).then(res => {
        if (res.data.success) {
          this.showMessage(res.data.message, 'success')
          this.comparePreview = res.data.preview
          this.compareFileName = res.data.fileName
          this.comparePreviewRows = res.data.previewRows || []
        } else {
          this.showMessage(res.data.message || '处理失败', 'error')
        }
      }).catch(err => {
        this.showMessage(err.response?.data?.message || err.message, 'error')
      }).finally(() => {
        this.loading = false
      })
    },
    submitExpensePreview() {
      if (!this.formExpense.file) {
        this.showMessage('请先选择文件', 'warning')
        return
      }
      this.expensePreviewing = true
      this.message = ''
      this.expensePreviewCols = []
      const formData = new FormData()
      formData.append('file', this.formExpense.file)
      // FormData 上传不能手动设置 Content-Type，浏览器会自动设置并带上 boundary
      axios.post('/api/finance/toolbox/expense-preview', formData).then(res => {
        if (res.data.success) {
          this.expensePreviewCols = res.data.columns || []
          this.showMessage('预览处理完成，共 ' + this.expensePreviewCols.length + ' 列', 'success')
        } else {
          this.showMessage(res.data.message || '预览处理失败', 'error')
        }
      }).catch(err => {
        this.showMessage(err.response?.data?.message || err.message, 'error')
      }).finally(() => {
        this.expensePreviewing = false
      })
    },
    submitExpenseSplit() {
      if (!this.formExpense.file) {
        this.showMessage('请先选择文件', 'warning')
        return
      }
      if (!this.formExpense.splitColumn) {
        this.showMessage('请先选择拆分列', 'warning')
        return
      }
      const formData = new FormData()
      formData.append('file', this.formExpense.file)
      formData.append('splitColumn', this.formExpense.splitColumn)
      this.loading = true
      this.message = ''
      axios.post('/api/finance/toolbox/expense-split', formData).then(res => {
        if (res.data.success) {
          this.showMessage(res.data.message, 'success')
          this.expenseDownloadName = res.data.fileName
        } else {
          this.showMessage(res.data.message || '处理失败', 'error')
        }
      }).catch(err => {
        this.showMessage(err.response?.data?.message || err.message, 'error')
      }).finally(() => {
        this.loading = false
      })
    },
    submitLaborSplit() {
      if (this.formLabor.files1.length === 0 || !this.formLabor.file2) {
        this.showMessage('请先选择代工费表格（至少1个）和发放记录表格', 'warning')
        return
      }
      if (!this.formLabor.sheet1Name || !this.formLabor.sheet2Name || !this.formLabor.sheetBName) {
        this.showMessage('请先填写工作表名称', 'warning')
        return
      }
      // 清空日志并开始记录
      this.laborLogs = []
      this.laborSplitting = true
      this.addLaborLog('代工费表格：共 ' + this.formLabor.files1.length + ' 个文件')
      this.formLabor.files1.forEach((f, i) => {
        this.addLaborLog('  [' + (i+1) + '] ' + f.name)
      })
      this.addLaborLog('发放记录表格：' + this.formLabor.file2.name)
      this.addLaborLog('  工作簿（A）：' + this.formLabor.sheet2Name)
      this.addLaborLog('  工作簿（B）：' + this.formLabor.sheetBName)
      this.addLaborLog('')

      const formData = new FormData()
      // 多个代工费文件：用同名 file1 追加
      this.formLabor.files1.forEach(f => formData.append('file1', f))
      formData.append('file2', this.formLabor.file2)
      formData.append('sheet1Name', this.formLabor.sheet1Name)
      formData.append('sheet2Name', this.formLabor.sheet2Name)
      formData.append('sheetBName', this.formLabor.sheetBName)

      this.loading = true
      this.message = ''
      // 使用批量处理 API（对齐 Python dgf_cf_frame.py 多文件 for 循环）
      axios.post('/api/finance/toolbox/labor-split-batch', formData).then(res => {
        if (res.data.success) {
          this.addLaborLog('  批量处理完成，共处理 ' + this.formLabor.files1.length + ' 个文件')
          this.addLaborLog('  汇总记录总数：' + (res.data.summaryCount || '未知'))
          this.addLaborLog('  拆分行总数：' + (res.data.splitCount || '未知'))
          this.addLaborLog('')
          const step4Details = res.data.step4Details || []
          step4Details.forEach(detail => this.addLaborLog(detail))
          const step5Details = res.data.step5Details || []
          step5Details.forEach(detail => this.addLaborLog(detail))
          const step5Result = res.data.step5Result || []
          step5Result.forEach(line => this.addLaborLog(line))
          this.addLaborLog('')
          this.addLaborLog('全部处理完毕！')
          this.showMessage(res.data.message, 'success')
          this.laborDownloadName = res.data.fileName
          this.laborSummaryFileNames = res.data.summaryFileNames || []
        } else {
          this.addLaborLog('[错误] ' + (res.data.message || '处理失败'))
          this.showMessage(res.data.message || '处理失败', 'error')
        }
      }).catch(err => {
        const msg = err.response?.data?.message || err.message
        this.addLaborLog('[错误] ' + msg)
        this.showMessage(msg, 'error')
      }).finally(() => {
        this.loading = false
        this.laborSplitting = false
      })
    },
    addLaborLog(msg) {
      this.laborLogs.push(msg)
    },
    downloadFile(fileName) {
      const url = '/api/finance/download/' + encodeURIComponent(fileName)
      const link = document.createElement('a')
      link.href = url
      link.download = fileName
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
    },
    // 每个Tab独立的刷新：只停止加载状态，保留文件选择、预览、下载、日志
    refreshTab(tabName) {
      this.loading = false
      this.laborSplitting = false
      this.expensePreviewing = false
      this.message = ''
      switch (tabName) {
        case 'fee-split':
          // 手续费拆分：只停loading，保留已选文件和下载结果
          break
        case 'data-compare':
          // 数据比较：只停loading，保留已选文件、日期筛选、预览结果、下载
          break
        case 'expense-split':
          // 报销拆分：重置预览状态（需要重新预览），但保留已选文件和下载结果
          this.expensePreviewCols = []
          this.formExpense.splitColumn = ''
          break
        case 'labor-split':
          // 代工费拆分：只停loading，保留已选文件、工作表选择、下载结果、日志
          break
      }
      const names = {
        'fee-split': '手续费拆分已刷新',
        'data-compare': '数据比较已刷新',
        'expense-split': '报销拆分已刷新',
        'labor-split': '代工费拆分已刷新'
      }
      this.showMessage(names[tabName] || '已刷新', 'success')
    },
    // 完全重置（离开财务工具箱或浏览器刷新时调用）
    resetAll() {
      this.activeTab = 'fee-split'
      this.loading = false
      this.message = ''
      this.feeFile = null
      this.feeDownloadName = ''
      this.formCompare = { file1: null, file2: null, sheet1Name: '', sheet2Name: '', startDate: '', endDate: '' }
      this.compareSheets1 = []
      this.compareSheets2 = []
      this.comparePreview = null
      this.comparePreviewRows = []
      this.compareFileName = ''
      this.expenseDownloadName = ''
      this.formExpense = { file: null, splitColumn: '' }
      this.expensePreviewing = false
      this.expensePreviewCols = []
      this.laborDownloadName = ''
      this.laborSummaryFileNames = []
      this.formLabor = { files1: [], file2: null, sheet1Name: '', sheet2Name: '', sheetBName: '' }
      this.laborSheets1 = []
      this.laborSheets2 = []
      this.laborLogs = []
      this.laborSplitting = false
    }
  }
}
</script>

